{"sql": "
-- Interesting - no customer has more than 1 order. Let me verify this
SELECT COUNT(*) FROM (
    SELECT customer_id, COUNT(DISTINCT order_id) AS num_orders
    FROM orders
    GROUP BY customer_id
    HAVING num_orders > 1
);
"}

{"sql": "
-- So every customer has exactly 1 order. Let me also check how many customers there are
SELECT COUNT(DISTINCT customer_id) FROM orders;
"}
